package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.std.StdKeyDeserializer;
import com.fasterxml.jackson.databind.introspect.AnnotatedMethod;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.EnumResolver;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.math.*;
import java.net.URI;
import java.net.URL;
import java.util.*;
import java.util.Calendar;
import java.util.Currency;
import java.util.Date;
import java.util.Locale;
import java.util.UUID;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.when;

public class StdKeyDeserializer__parse_TriageGen0Test {

    private DeserializationContext ctxt;
    private TestKeyDeserializer deserializer;

    // Constants for _kind values based on typical Jackson implementation
    private static final int TYPE_BOOLEAN = 1;
    private static final int TYPE_BYTE = 2;
    private static final int TYPE_SHORT = 3;
    private static final int TYPE_CHAR = 4;
    private static final int TYPE_INT = 5;
    private static final int TYPE_LONG = 6;
    private static final int TYPE_FLOAT = 7;
    private static final int TYPE_DOUBLE = 8;
    private static final int TYPE_LOCALE = 9;
    private static final int TYPE_CURRENCY = 10;
    private static final int TYPE_DATE = 11;
    private static final int TYPE_CALENDAR = 12;
    private static final int TYPE_UUID = 13;
    private static final int TYPE_URI = 14;
    private static final int TYPE_URL = 15;
    private static final int TYPE_CLASS = 16;

    // Subclass to access protected method and override helper methods for testing
    private static class TestKeyDeserializer extends StdKeyDeserializer {
        private int kind;
        private Class<?> keyClass;
        private FromStringDeserializer<?> deser;

        protected TestKeyDeserializer(int kind, Class<?> cls) {
            super(kind, cls);
            this.kind = kind;
            this.keyClass = cls;
        }

        protected TestKeyDeserializer(int kind, Class<?> cls, FromStringDeserializer<?> deser) {
            super(kind, cls, deser);
            this.kind = kind;
            this.keyClass = cls;
            this.deser = deser;
        }

        // Reflection or manual override of the kind field is needed because it's private in StdKeyDeserializer
        // Since we can't easily change the private field '_kind' via super, we simulate the logic 
        // or use a custom implementation that mimics the switch.
        // However, in a real test environment, we'd use Reflection to set the private '_kind'.

        public void setKind(int kind) {
            try {
                java.lang.reflect.Field field = StdKeyDeserializer.class.getDeclaredField("_kind");
                field.setAccessible(true);
                field.set(this, kind);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        protected int _parseInt(String key) { return Integer.parseInt(key); }
        @Override
        protected long _parseLong(String key) { return Long.parseLong(key); }
        @Override
        protected double _parseDouble(String key) { return Double.parseDouble(key); }

        @Override
        public Object deserializeKey(String key, DeserializationContext ctxt) throws IOException {
            try {
                return _parse(key, ctxt);
            } catch (Exception e) {
                if (e instanceof IOException) throw (IOException) e;
                throw new RuntimeException(e);
            }
        }
    }

    // Mock for FromStringDeserializer
    public abstract static class FromStringDeserializer<T> {
        public abstract T _deserialize(String key, DeserializationContext ctxt) throws IOException;
    }

    @Before
    public void setUp() {
        ctxt = Mockito.mock(DeserializationContext.class);
        deserializer = new TestKeyDeserializer(TYPE_BOOLEAN, String.class);
    }

    @Test
    public void testBoolean() throws Exception {
        deserializer.setKind(TYPE_BOOLEAN);
        assertEquals(Boolean.TRUE, deserializer._parse("true", ctxt));
        assertEquals(Boolean.FALSE, deserializer._parse("false", ctxt));
        when(ctxt.weirdKeyException(any(), eq("invalid"), anyString())).thenThrow(new IOException("error"));
        try {
            deserializer._parse("invalid", ctxt);
        } catch (Exception e) {
            // expected
        }
    }

    @Test
    public void testByte() throws Exception {
        deserializer.setKind(TYPE_BYTE);
        assertEquals(Byte.valueOf((byte) 127), deserializer._parse("127", ctxt));
        assertEquals(Byte.valueOf((byte) -128), deserializer._parse("-128", ctxt));
        assertEquals(Byte.valueOf((byte) 255), deserializer._parse("255", ctxt));

        when(ctxt.weirdKeyException(any(), anyString(), contains("overflow"))).thenThrow(new IOException("overflow"));
        try {
            deserializer._parse("256", ctxt);
        } catch (Exception e) {}
        try {
            deserializer._parse("-129", ctxt);
        } catch (Exception e) {}
    }

    @Test
    public void testShort() throws Exception {
        deserializer.setKind(TYPE_SHORT);
        assertEquals(Short.valueOf((short) 32767), deserializer._parse("32767", ctxt));
        assertEquals(Short.valueOf((short) -32768), deserializer._parse("-32768", ctxt));

        when(ctxt.weirdKeyException(any(), anyString(), contains("overflow"))).thenThrow(new IOException("overflow"));
        try {
            deserializer._parse("32768", ctxt);
        } catch (Exception e) {}
    }

    @Test
    public void testChar() throws Exception {
        deserializer.setKind(TYPE_CHAR);
        assertEquals('A', deserializer._parse("A", ctxt));
        when(ctxt.weirdKeyException(any(), anyString(), contains("1-character"))).thenThrow(new IOException("error"));
        try {
            deserializer._parse("AB", ctxt);
        } catch (Exception e) {}
    }

    @Test
    public void testInt() throws Exception {
        deserializer.setKind(TYPE_INT);
        assertEquals(123, deserializer._parse("123", ctxt));
    }

    @Test
    public void testLong() throws Exception {
        deserializer.setKind(TYPE_LONG);
        assertEquals(123456789L, deserializer._parse("123456789", ctxt));
    }

    @Test
    public void testFloat() throws Exception {
        deserializer.setKind(TYPE_FLOAT);
        assertEquals(1.5f, (float) deserializer._parse("1.5", ctxt), 0.001);
    }

    @Test
    public void testDouble() throws Exception {
        deserializer.setKind(TYPE_DOUBLE);
        assertEquals(1.5, (double) deserializer._parse("1.5", ctxt), 0.001);
    }

    @Test
    public void testLocaleAndCurrency() throws Exception {
        FromStringDeserializer<?> mockDeser = Mockito.mock(FromStringDeserializer.class);
        deserializer = new TestKeyDeserializer(TYPE_LOCALE, String.class, mockDeser);

        deserializer.setKind(TYPE_LOCALE);
        when(mockDeser._deserialize("en_US", ctxt)).thenReturn("en_US");
        assertEquals("en_US", deserializer._parse("en_US", ctxt));

        when(mockDeser._deserialize(anyString(), any())).thenThrow(new IOException("IO Error"));
        when(ctxt.weirdKeyException(any(), anyString(), contains("locale"))).thenThrow(new IOException("locale error"));
        try {
            deserializer._parse("err", ctxt);
        } catch (Exception e) {}

        deserializer.setKind(TYPE_CURRENCY);
        when(ctxt.weirdKeyException(any(), anyString(), contains("currency"))).thenThrow(new IOException("currency error"));
        try {
            deserializer._parse("err", ctxt);
        } catch (Exception e) {}
    }

    @Test
    public void testDateAndCalendar() throws Exception {
        deserializer.setKind(TYPE_DATE);
        Date now = new Date();
        when(ctxt.parseDate("now")).thenReturn(now);
        assertEquals(now, deserializer._parse("now", ctxt));

        deserializer.setKind(TYPE_CALENDAR);
        when(ctxt.parseDate("null")).thenReturn(null);
        assertNull(deserializer._parse("null", ctxt));

        Calendar cal = Calendar.getInstance();
        when(ctxt.parseDate("cal")).thenReturn(now);
        when(ctxt.constructCalendar(now)).thenReturn(cal);
        assertEquals(cal, deserializer._parse("cal", ctxt));
    }

    @Test
    public void testUUID() throws Exception {
        deserializer.setKind(TYPE_UUID);
        UUID uuid = UUID.randomUUID();
        assertEquals(uuid, deserializer._parse(uuid.toString(), ctxt));
    }

    @Test
    public void testURI() throws Exception {
        deserializer.setKind(TYPE_URI);
        URI uri = URI.create("http://test.com");
        assertEquals(uri, deserializer._parse("http://test.com", ctxt));
    }

    @Test
    public void testURL() throws Exception {
        deserializer.setKind(TYPE_URL);
        URL url = new URL("http://test.com");
        assertEquals(url, deserializer._parse("http://test.com", ctxt));
    }

    @Test
    public void testClass() throws Exception {
        deserializer.setKind(TYPE_CLASS);
        when(ctxt.findClass("java.lang.String")).thenReturn(String.class);
        assertEquals(String.class, deserializer._parse("java.lang.String", ctxt));

        when(ctxt.findClass(anyString())).thenThrow(new RuntimeException("not found"));
        when(ctxt.weirdKeyException(any(), anyString(), contains("Class"))).thenThrow(new IOException("error"));
        try {
            deserializer._parse("invalid", ctxt);
        } catch (Exception e) {}
    }

    @Test
    public void testDefaultReturnNull() throws Exception {
        // To test the final return null, we need a kind that doesn't match anything
        // Since _kind is an int, we can pass a value not handled in switch
        deserializer.setKind(999);
        assertNull(deserializer._parse("any", ctxt));
    }
}
